-- Germany SEO master-plan wave 1: publish the remaining nine application pages.
-- Claims remain application-specific and require technical validation before a guarantee.
INSERT INTO public.solution_pages (slug, page_kind, title, excerpt, content_html, technical_specs, proof_points, seo_title, seo_description, keywords, is_published, display_order)
VALUES
('endustriyel-barkod-etiketleri', 'solution', 'Endüstriyel Barkod Etiketleri', 'Üretim, depo ve sevkiyat süreçleri için okunabilirliği ve uygulama koşullarını birlikte değerlendiren barkod etiket çözümleri.', '<h2>Endüstriyel barkod etiketlerinde doğru seçim</h2><p>Endüstriyel barkod etiketi seçimi; yüzey, sıcaklık, nem, sürtünme, baskı yöntemi ve kullanım süresi birlikte değerlendirilerek yapılmalıdır.</p><h3>Uygulama doğrulaması</h3><p>Malzeme, yapışkan ve ribon kombinasyonu gerçek yüzey ve çevre koşullarında test edilmelidir. Okunabilirlik ve değişken veri baskısı teklif öncesinde netleştirilir.</p>', '{"applications":"Üretim, depo ve sevkiyat","validation":"Yüzey ve çevre koşullarında test","printing":"Termal transfer veya uygulamaya uygun baskı"}'::jsonb, '["Uygulamaya göre malzeme seçimi","Barkod okunabilirliği için test yaklaşımı","Değişken veri ve izlenebilirlik desteği"]'::jsonb, 'Endüstriyel Barkod Etiketleri | Rotabil Etiket', 'Üretim, depo ve sevkiyat süreçleri için uygulamaya özel endüstriyel barkod etiketi çözümleri.', 'endüstriyel barkod etiketleri, üretim etiketleri, depo barkod etiketleri', true, 5),
('varlik-takip-etiketleri', 'solution', 'Varlık Takip Etiketleri', 'Makine, ekipman ve demirbaşların uzun süreli tanımlanması için yüzey ve kullanım koşullarına göre tasarlanan etiket çözümleri.', '<h2>Varlık takibi için dayanıklı kimliklendirme</h2><p>Varlık takip etiketlerinde yüzey tipi, temizleme yöntemi, iç veya dış ortam, barkod ya da RFID kullanımı ve beklenen kullanım süresi belirleyicidir.</p><h3>Veri yapısı ve uygulama</h3><p>Etiket tasarımı, işletmenin varlık kayıt sistemiyle uyumlu veri yapısına göre hazırlanır. Yapışma ve okunabilirlik iddiaları uygulama yüzeyinde doğrulanmalıdır.</p>', '{"applications":"Makine, ekipman ve demirbaş","technologies":"Barkod veya RFID","validation":"Yüzey ve kullanım süresi doğrulaması"}'::jsonb, '["Barkod ve RFID seçenekleri","Yüzeye göre yapışkan seçimi","Varlık kayıt sistemiyle uyumlu veri yapısı"]'::jsonb, 'Varlık Takip Etiketleri | Rotabil Etiket', 'Makine, ekipman ve demirbaşlar için barkod ve RFID tabanlı varlık takip etiketi çözümleri.', 'varlık takip etiketleri, demirbaş etiketleri, ekipman barkod etiketleri', true, 6),
('ozel-endustriyel-etiket-uretimi', 'solution', 'Özel Endüstriyel Etiket Üretimi', 'Ölçü, malzeme, yapışkan, baskı ve veri gereksinimleri belirlenerek uygulamaya özel endüstriyel etiket üretimi.', '<h2>Uygulamaya göre özel etiket üretimi</h2><p>Özel üretim sürecinde etiket ölçüsü, malzeme, yapışkan, baskı teknolojisi, sarım yönü ve paketleme şartları birlikte planlanır.</p><h3>Teknik brif ve numune</h3><p>Doğru çözüm için yüzey, çevre koşulları, kullanım süresi ve baskı verisi incelenir. Gerekli durumlarda numune ve uygulama testiyle üretim öncesi doğrulama yapılır.</p>', '{"scope":"Ölçü, malzeme, yapışkan ve baskı","process":"Teknik brif, numune ve üretim doğrulaması","output":"Uygulamaya özel etiket konstrüksiyonu"}'::jsonb, '["Esnek ölçü ve malzeme seçimi","Numune ile uygulama doğrulaması","Değişken veri ve paketleme seçenekleri"]'::jsonb, 'Özel Endüstriyel Etiket Üretimi | Rotabil Etiket', 'Ölçü, malzeme, yapışkan ve baskı gereksinimlerinize göre özel endüstriyel etiket üretimi.', 'özel endüstriyel etiket, etiket üretimi, özel ölçü etiket', true, 7),
('celik-sanayi-etiketleri', 'industry', 'Çelik Sanayi Etiketleri', 'Çelik üretimi ve metal işleme süreçlerinde sıcaklık, yüzey ve aşınma koşullarına göre doğrulanan kimliklendirme çözümleri.', '<h2>Çelik üretiminde izlenebilirlik</h2><p>Çelik ve metal uygulamalarında etiket seçimi; sıcaklık profili, yüzey yapısı, yağ ve nem, uygulama zamanı ve barkod okunabilirliği dikkate alınarak yapılır.</p><h3>Garanti yerine doğrulama</h3><p>Her üretim hattı farklı olduğundan yüksek sıcaklık veya dayanım iddiaları gerçek proses koşullarında test edilmelidir.</p>', '{"applications":"Çelik üretimi ve metal işleme","checks":"Sıcaklık, yüzey, yağ, nem ve aşınma","note":"Uygulama testi gereklidir"}'::jsonb, '["Proses koşullarına göre seçim","İzlenebilirlik için barkod seçenekleri","Uygulama testiyle teknik doğrulama"]'::jsonb, 'Çelik Sanayi Etiketleri | Rotabil Etiket', 'Çelik üretimi ve metal işleme süreçleri için uygulama koşulları doğrulanmış etiket çözümleri.', 'çelik sanayi etiketleri, metal etiketleri, yüksek sıcaklık etiketleri', true, 40),
('dokum-ve-metal-isleme-etiketleri', 'industry', 'Döküm ve Metal İşleme Etiketleri', 'Dökümhane ve metal işleme hatlarında yüzey, sıcaklık ve proses akışına göre seçilen takip ve barkod etiketleri.', '<h2>Dökümhane süreçlerinde kimliklendirme</h2><p>Döküm ve metal işleme etiketlerinde uygulama yüzeyi, proses sıcaklığı, yağ, toz, sürtünme ve etiketin hangi aşamada uygulanacağı birlikte incelenir.</p><h3>İzlenebilirlik akışı</h3><p>Etiket verisi üretim emri, parti veya parça bilgisiyle eşleştirilebilir. Okuma testi ve baskı yöntemi işletmenin mevcut sistemine göre planlanır.</p>', '{"applications":"Dökümhane ve metal işleme","variables":"Yüzey, sıcaklık, yağ, toz ve sürtünme","technologies":"Barkod ve değişken veri"}'::jsonb, '["Proses aşamasına göre uygulama","Parti ve üretim emri takibi","Baskı ve okuma testi"]'::jsonb, 'Döküm ve Metal İşleme Etiketleri | Rotabil Etiket', 'Dökümhane ve metal işleme hatları için proses koşullarına göre etiket ve izlenebilirlik çözümleri.', 'dökümhane etiketleri, metal işleme etiketleri, parça takip etiketleri', true, 41),
('otomotiv-komponent-etiketleri', 'industry', 'Otomotiv Komponent Etiketleri', 'Otomotiv parçalarının üretim, kalite ve lojistik akışında tanımlanması için barkod ve RFID tabanlı etiket seçenekleri.', '<h2>Otomotiv parça izlenebilirliği</h2><p>Otomotiv komponent etiketlerinde parça yüzeyi, üretim süreci, okunabilirlik, veri yapısı ve etiketin lojistik boyunca kalma süresi değerlendirilir.</p><h3>Tedarik zinciri uyumu</h3><p>Değişken veri, parti veya seri numarası işletmenin izlenebilirlik sistemine uygun olarak hazırlanır. Malzeme ve yapışkan seçimi gerçek parça üzerinde doğrulanmalıdır.</p>', '{"applications":"Otomotiv komponentleri ve lojistik","data":"Seri, parti ve parça bilgisi","validation":"Parça yüzeyinde baskı ve yapışma testi"}'::jsonb, '["Seri ve parti takibi","Barkod veya RFID seçenekleri","Parça yüzeyinde uygulama doğrulaması"]'::jsonb, 'Otomotiv Komponent Etiketleri | Rotabil Etiket', 'Otomotiv parçaları için üretim, kalite ve lojistik izlenebilirliğine uygun etiket çözümleri.', 'otomotiv komponent etiketleri, parça takip etiketleri, otomotiv barkod', true, 42),
('depo-ve-lojistik-etiketleri', 'industry', 'Depo ve Lojistik Etiketleri', 'Depo adresleri, koli, palet ve sevkiyat süreçleri için okunabilir barkod ve tanımlama etiketleri.', '<h2>Depo akışında okunabilir etiketler</h2><p>Depo ve lojistik etiketleri; tarama mesafesi, etiket boyutu, yüzey, termal transfer veya direkt termal baskı ve kullanım süresi dikkate alınarak seçilir.</p><h3>Operasyonel uyum</h3><p>Veri alanları ve barkod standardı mevcut WMS veya ERP akışıyla eşleştirilmelidir. Etiket yerleşimi ve baskı kalitesi sevkiyat öncesi kontrol edilir.</p>', '{"applications":"Koli, palet, raf ve sevkiyat","systems":"WMS/ERP veri akışı","printing":"Termal transfer veya direkt termal"}'::jsonb, '["Depo adres ve palet etiketleri","WMS/ERP uyumlu veri","Tarama mesafesine göre tasarım"]'::jsonb, 'Depo ve Lojistik Etiketleri | Rotabil Etiket', 'Depo, koli, palet ve sevkiyat süreçleri için okunabilir barkod ve lojistik etiketleri.', 'depo etiketleri, lojistik barkod etiketleri, palet etiketleri', true, 43),
('soguk-hava-ve-dondurucu-etiketleri', 'industry', 'Soğuk Hava ve Dondurucu Etiketleri', 'Soğuk depo, dondurucu ve nemli lojistik ortamlarında yüzey ve sıcaklık koşullarına göre doğrulanan etiket çözümleri.', '<h2>Soğuk zincir için etiket seçimi</h2><p>Soğuk hava ve dondurucu etiketlerinde uygulama sıcaklığı, yoğuşma, yüzey tipi, depolama süresi ve baskı yöntemi birlikte değerlendirilir.</p><h3>Uygulama öncesi kontrol</h3><p>Etiketin soğuk yüzeye yapışması ve barkodun okunabilirliği gerçek depolama koşullarında test edilmelidir. Her uygulama için uygun malzeme ve yapışkan ayrıca belirlenir.</p>', '{"applications":"Soğuk depo ve dondurucu","checks":"Sıcaklık, yoğuşma, yüzey ve depolama süresi","note":"Gerçek koşullarda test gerekir"}'::jsonb, '["Soğuk yüzeyde yapışma değerlendirmesi","Yoğuşma ve nem kontrolü","Barkod okunabilirlik testi"]'::jsonb, 'Soğuk Hava ve Dondurucu Etiketleri | Rotabil Etiket', 'Soğuk depo ve dondurucu uygulamaları için sıcaklık ve nem koşulları doğrulanmış etiket çözümleri.', 'soğuk depo etiketleri, dondurucu etiketleri, soğuk zincir etiketleri', true, 44),
('endustriyel-rfid-izlenebilirlik', 'solution', 'Endüstriyel RFID İzlenebilirlik', 'Depo, varlık ve üretim akışlarında RFID kullanımını yüzey, frekans, okuma mesafesi ve veri yapısıyla birlikte değerlendiren çözüm.', '<h2>RFID ile endüstriyel izlenebilirlik</h2><p>RFID çözümünün başarısı yalnızca etiket üzerinde değil; frekans, yüzey, okuyucu konumu, okuma mesafesi, encoding ve işletme veri modeli birlikte değerlendirilerek belirlenir.</p><h3>Pilot uygulama</h3><p>Önce gerçek ürün, palet veya varlık üzerinde pilot okuma testi yapılmalı; ardından etiket konstrüksiyonu ve veri akışı netleştirilmelidir.</p>', '{"technology":"UHF RFID ve barkod seçenekleri","checks":"Yüzey, frekans, okuma mesafesi ve encoding","process":"Pilot test ve veri akışı doğrulaması"}'::jsonb, '["Yüzeye göre RFID seçimi","Pilot okuma testi","Encoding ve sistem entegrasyonu"]'::jsonb, 'Endüstriyel RFID İzlenebilirlik | Rotabil Etiket', 'Depo, varlık ve üretim akışları için pilot test ve veri doğrulamasına dayalı RFID çözümleri.', 'endüstriyel RFID, RFID izlenebilirlik, UHF RFID etiket', true, 45)
ON CONFLICT (slug) DO UPDATE SET is_published = true, updated_at = now();

-- German translations are the first live localization wave for the Germany market.
INSERT INTO public.solution_page_translations (solution_page_id, language_code, slug, title, excerpt, content_html, technical_specs, seo_title, seo_description, keywords)
SELECT page.id, translation.language_code, translation.slug, translation.title, translation.excerpt, translation.content_html, '{}'::jsonb, translation.seo_title, translation.seo_description, translation.keywords
FROM public.solution_pages page
JOIN (VALUES
('endustriyel-barkod-etiketleri','de','industrielle-barcode-etiketten','Industrielle Barcode-Etiketten','Anwendungsspezifische Barcode-Etiketten für Produktion, Lager und Versand.','<h2>Die richtige Auswahl für industrielle Barcode-Etiketten</h2><p>Oberfläche, Temperatur, Feuchtigkeit, Abrieb, Druckverfahren und Einsatzdauer müssen gemeinsam bewertet werden.</p><h3>Anwendungsprüfung</h3><p>Material, Klebstoff und Farbband sollten unter den realen Bedingungen geprüft werden. Lesbarkeit und variable Daten werden vor dem Angebot abgestimmt.</p>','Industrielle Barcode-Etiketten | Rotabil Etiket','Anwendungsspezifische Barcode-Etiketten für Produktion, Lager und Versand.','Industrieetiketten, Barcode-Etiketten, Lageretiketten'),
('varlik-takip-etiketleri','de','asset-tracking-etiketten','Asset-Tracking-Etiketten','Barcode- und RFID-Etiketten für Maschinen, Anlagen und Betriebsmittel.','<h2>Identifikation für die Anlagenverfolgung</h2><p>Oberfläche, Reinigungsverfahren, Innen- oder Außenbereich sowie Barcode- oder RFID-Nutzung bestimmen die Auswahl.</p><h3>Daten und Anwendung</h3><p>Das Etikett wird an die Datenstruktur des Anlagenregisters angepasst. Haftung und Lesbarkeit müssen auf der realen Oberfläche geprüft werden.</p>','Asset-Tracking-Etiketten | Rotabil Etiket','Barcode- und RFID-Etiketten für Maschinen, Anlagen und Betriebsmittel.','Asset Tracking, Anlagenetiketten, RFID-Etiketten'),
('ozel-endustriyel-etiket-uretimi','de','individuelle-industrieetiketten','Individuelle Industrieetiketten','Individuelle Etikettenproduktion nach Maß, Material, Klebstoff, Druck und Datenanforderungen.','<h2>Individuelle Etiketten nach Anwendung</h2><p>Format, Material, Klebstoff, Drucktechnologie, Wickelrichtung und Verpackung werden gemeinsam geplant.</p><h3>Technisches Briefing und Muster</h3><p>Oberfläche, Umgebung, Einsatzdauer und Druckdaten werden vor der Produktion geprüft. Bei Bedarf erfolgt eine Musterprüfung.</p>','Individuelle Industrieetiketten | Rotabil Etiket','Individuelle Etikettenproduktion nach Maß, Material, Klebstoff und Druckanforderung.','individuelle Industrieetiketten, Etikettenproduktion, Sonderetiketten'),
('celik-sanayi-etiketleri','de','etiketten-fuer-die-stahlindustrie','Etiketten für die Stahlindustrie','Etikettenlösungen für Stahl- und Metallprozesse nach Prüfung von Temperatur, Oberfläche und Abrieb.','<h2>Rückverfolgbarkeit in der Stahlproduktion</h2><p>Temperaturprofil, Oberfläche, Öl, Feuchtigkeit, Abrieb und der Applikationszeitpunkt müssen gemeinsam geprüft werden.</p><h3>Validierung statt pauschaler Garantie</h3><p>Jede Linie ist anders. Aussagen zu Temperatur- oder Beständigkeit müssen unter realen Prozessbedingungen validiert werden.</p>','Etiketten für die Stahlindustrie | Rotabil Etiket','Etikettenlösungen für Stahl- und Metallprozesse nach Prüfung der Einsatzbedingungen.','Stahlindustrie-Etiketten, Metall-Etiketten, Hochtemperatur-Etiketten'),
('dokum-ve-metal-isleme-etiketleri','de','etiketten-fuer-giesserei-und-metallverarbeitung','Etiketten für Gießerei und Metallverarbeitung','Etiketten für Gießerei- und Metallprozesse nach Prüfung von Oberfläche, Temperatur und Prozessablauf.','<h2>Identifikation in der Gießerei</h2><p>Oberfläche, Prozesstemperatur, Öl, Staub, Abrieb und der Applikationsschritt werden vor der Auswahl geprüft.</p><h3>Rückverfolgbarkeit</h3><p>Daten können mit Auftrag, Charge oder Teileinformation verbunden werden. Druck- und Lesetests werden an den vorhandenen Systemen ausgerichtet.</p>','Etiketten für Gießerei und Metallverarbeitung | Rotabil Etiket','Etiketten für Gießerei- und Metallprozesse nach Prüfung der Einsatzbedingungen.','Gießerei-Etiketten, Metallverarbeitung, Teileetiketten'),
('otomotiv-komponent-etiketleri','de','etiketten-fuer-automotive-komponenten','Etiketten für Automotive-Komponenten','Barcode- und RFID-Etiketten für Produktion, Qualität und Logistik von Automotive-Komponenten.','<h2>Rückverfolgbarkeit von Automotive-Teilen</h2><p>Oberfläche, Prozess, Lesbarkeit, Datenstruktur und Verbleib des Etiketts in der Lieferkette müssen bewertet werden.</p><h3>Lieferkettenkompatibilität</h3><p>Variable Daten werden an das bestehende Rückverfolgbarkeitssystem angepasst. Material und Klebstoff sollten auf dem realen Bauteil geprüft werden.</p>','Etiketten für Automotive-Komponenten | Rotabil Etiket','Barcode- und RFID-Etiketten für die Rückverfolgbarkeit von Automotive-Komponenten.','Automotive-Etiketten, Teileetiketten, Barcode-Etiketten'),
('depo-ve-lojistik-etiketleri','de','lager-und-logistiketiketten','Lager- und Logistiketiketten','Lesbare Barcode- und Identifikationsetiketten für Lager, Kartons, Paletten und Versand.','<h2>Lesbare Etiketten für Lagerprozesse</h2><p>Scanabstand, Format, Oberfläche, Druckverfahren und Einsatzdauer bestimmen die Etikettenauswahl.</p><h3>Passend zum Betriebsablauf</h3><p>Datenfelder und Barcode werden mit WMS oder ERP abgestimmt. Platzierung und Druckqualität werden vor dem Versand kontrolliert.</p>','Lager- und Logistiketiketten | Rotabil Etiket','Lesbare Barcode- und Logistiketiketten für Lager, Paletten und Versand.','Lageretiketten, Logistiketiketten, Palettenetiketten'),
('soguk-hava-ve-dondurucu-etiketleri','de','etiketten-fuer-kuehlhaus-und-tiefkuehler','Etiketten für Kühlhaus und Tiefkühler','Etikettenlösungen für Kühlhaus, Tiefkühler und feuchte Logistikumgebungen nach Prüfung von Oberfläche und Temperatur.','<h2>Etiketten für die Kühlkette</h2><p>Applikationstemperatur, Kondensation, Oberfläche, Lagerdauer und Druckverfahren werden gemeinsam bewertet.</p><h3>Prüfung vor der Anwendung</h3><p>Haftung auf kalten Oberflächen und Barcode-Lesbarkeit müssen unter den realen Lagerbedingungen geprüft werden.</p>','Etiketten für Kühlhaus und Tiefkühler | Rotabil Etiket','Etikettenlösungen für Kühlhaus und Tiefkühler nach Prüfung von Temperatur und Feuchtigkeit.','Kühlhaus-Etiketten, Tiefkühletiketten, Kühlkettenetiketten'),
('endustriyel-rfid-izlenebilirlik','de','industrielle-rfid-rueckverfolgbarkeit','Industrielle RFID-Rückverfolgbarkeit','RFID-Lösungen für Lager, Anlagen und Produktion nach Prüfung von Oberfläche, Frequenz, Lesereichweite und Datenstruktur.','<h2>Industrielle Rückverfolgbarkeit mit RFID</h2><p>Frequenz, Oberfläche, Lesegerät, Reichweite, Encoding und Datenmodell müssen gemeinsam betrachtet werden.</p><h3>Pilotanwendung</h3><p>Zuerst wird ein Lesetest am realen Produkt, der Palette oder Anlage durchgeführt. Danach werden Konstruktion und Datenfluss festgelegt.</p>','Industrielle RFID-Rückverfolgbarkeit | Rotabil Etiket','RFID-Lösungen für Lager, Anlagen und Produktion mit Pilotprüfung und validiertem Datenfluss.','industrielle RFID, RFID-Rückverfolgbarkeit, UHF RFID')
) AS translation(base_slug, language_code, slug, title, excerpt, content_html, seo_title, seo_description, keywords) ON page.slug = translation.base_slug
ON CONFLICT (solution_page_id, language_code) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, excerpt = EXCLUDED.excerpt, content_html = EXCLUDED.content_html, seo_title = EXCLUDED.seo_title, seo_description = EXCLUDED.seo_description, keywords = EXCLUDED.keywords, updated_at = now();
